INSERT INTO converted_files (title, description, file_url, file_name, s3_key, size_bytes) VALUES ('Счет на оплату № СП 206520 от 30.09.2026 OData', 'Счёт ИНСТРОТЕХ № СП206520 от 30.09.2026 (Huter, Eurolux, Вихрь, Ресанта) по правилу «Создание файла для OData». Восемь колонок: Артикул (из колонки «Артикул», текстом), Штрихкод (в счёте нет — пусто), Наименование (как в счёте, со звёздочкой), Количество, Цена с НДС, Страна, Номер ГТД, Номер РНПТ (в счёте нет — пусто). 277 строк, 785 шт. Итог счёта 3 038 692,93 руб.; «количество × цена» даёт 3 038 693,08 руб. — расхождение 0,15 руб. из-за округления цены до копеек у поставщика (в 69 строках сумма в счёте отличается от количество × цена на 1–16 коп.).', '/converted/schet-sp-206520-30-09-2026-odata.xlsx', 'Счет на оплату № СП 206520 от 30.09.2026 OData.xlsx', 'converted/schet-sp-206520-30-09-2026-odata.xlsx', 20898);